package com.wiseway.service;
import com.wiseway.api.ApiDtos.*; import com.wiseway.domain.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class RecommendationService {
 private final LocationService catalog; private final RoutingProvider routing; private final FareCalculationService fares;
 public RecommendationService(LocationService c,RoutingProvider r,FareCalculationService f){catalog=c;routing=r;fares=f;}
 public CompareResponse compare(CompareRequest r,Set<String> excluded){
  var from=location(r.origin(),r.originLatitude(),r.originLongitude()); var to=location(r.destination(),r.destinationLatitude(),r.destinationLongitude());
  if(from.isEmpty()||to.isEmpty()) return empty("UNKNOWN_LOCATION","Select a valid location suggestion before comparing.");
  var route=routing.route(from.get(),to.get()); if(route.isEmpty()) return empty("NO_ROUTE","No road route was returned by the configured provider. No distance-based fares were fabricated.");
  var verified=route.get().source().equals("WISEWAY_CURATED_ROUTE")?Set.of("BUS","METRO"):Set.<String>of(); var options=new ArrayList<TransportOption>();
  for(var mode:List.of(TransportMode.BUS,TransportMode.METRO,TransportMode.TRAIN,TransportMode.AUTO,TransportMode.CAB)){var fare=fares.calculate(mode,(int)Math.round(route.get().distanceMetres())); if(fare.amount()!=null&&(mode==TransportMode.AUTO||mode==TransportMode.CAB||verified.contains(mode.name()))) options.add(new TransportOption(mode.name().toLowerCase()+"-route",mode,Math.max(1,(int)Math.round(route.get().durationSeconds()/60))+(mode==TransportMode.BUS?8:0),fare.amount(),"INR",mode==TransportMode.BUS?1:0,mode==TransportMode.CAB?1:4,"Route-specific estimate for "+from.get().name()+" → "+to.get().name()+"."));}
  var c=r.constraints(); var result=RecommendationEngine.recommend(options,r.preference()==null?PreferenceProfile.BALANCED:r.preference(),new RecommendationEngine.Constraints(c==null?null:c.maxFare(),r.departureAt(),c==null?null:c.arriveBy()),excluded);
  return new CompareResponse("ROUTE_"+route.get().source(),"Distance and duration from "+route.get().source()+". Fares are formula-based estimates; transit availability is not verified unless supplied by a transit dataset.",result.feasible().stream().map(x->option(x,route.get(),verified)).toList(),result.infeasible().stream().map(x->new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),null,List.of(),x.reasons(),verified.contains(x.option().mode().name())?"AVAILABLE":"ESTIMATED_ONLY","CALCULATED_ESTIMATE",route.get().source())).toList(),result.noFit(),result.message(),route.get().distanceMetres(),route.get().durationSeconds(),route.get().geometry(),route.get().source());
 }
 private Optional<LocationService.Location> location(String name,Double lat,Double lon){return catalog.resolve(name).or(()->lat!=null&&lon!=null?Optional.of(new LocationService.Location("resolved",name,"Selected location",lat,lon)):Optional.empty());}
 public PlanBResponse planB(PlanBRequest r){var excluded=new HashSet<>(Optional.ofNullable(r.excludeOptionIds()).orElse(List.of()));if(r.scenario()==PlanBScenario.MISSED_SERVICE)excluded.add("bus-route");if(r.scenario()==PlanBScenario.ROUTE_DISRUPTED&&excluded.isEmpty())excluded.add("train-route");var profile=switch(r.scenario()){case RUNNING_LATE,MISSED_SERVICE,ROUTE_DISRUPTED->PreferenceProfile.TIME_SAVER;case SAVE_MONEY,EXTRA_TIME->PreferenceProfile.BUDGET_SAVER;};var c=compare(new CompareRequest(r.origin(),r.destination(),r.originLatitude(),r.originLongitude(),r.destinationLatitude(),r.destinationLongitude(),r.departureAt(),profile,r.constraints()),excluded);var explanation=scenarioExplanation(r.scenario());return new PlanBResponse(r.scenario(),c.dataQuality(),"Simulated Plan B: "+explanation+" Not a live disruption alert.",c.feasibleOptions().isEmpty()?null:c.feasibleOptions().get(0),c.feasibleOptions().size()>1?c.feasibleOptions().subList(1,c.feasibleOptions().size()):List.of(),c.noFeasibleOption(),c.message()==null?explanation:c.message()+" "+explanation,c.routeDistanceMetres(),c.routeDurationSeconds(),c.routeGeometry(),c.routeSource());}
 private String scenarioExplanation(PlanBScenario s){return switch(s){case RUNNING_LATE->"Prioritized shorter estimated duration.";case MISSED_SERVICE->"Excluded the simulated missed bus service and prioritized time.";case ROUTE_DISRUPTED->"Applied the simulated disruption exclusion and prioritized time.";case SAVE_MONEY->"Prioritized the lowest estimated fare.";case EXTRA_TIME->"Prioritized cheaper options because extra time is available.";};}
 private OptionResponse option(RecommendationEngine.RankedOption x,RoutingProvider.Route r,Set<String> v){return new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),x.score(),x.reasons(),List.of(),v.contains(x.option().mode().name())?"AVAILABLE":"ESTIMATED_ONLY","CALCULATED_ESTIMATE",r.source()+" · "+Math.round(r.distanceMetres())+"m road route");}
 private CompareResponse empty(String q,String m){return new CompareResponse(q,m,List.of(),List.of(),true,m,null,null,null,null);}
}
